  ('pt-BR', 'site.doctor.sanitization.builtIn', $json$"Os detectores da plataforma sempre rodam: tokens, chaves, senhas, CPF, CNPJ, e-mail, telefone e cartão. As regras daqui se somam a eles e valem para os Eventos que chegarem daqui em diante."$json$::jsonb),
