  ('hi', 'site.doctor.sanitization.title', $json$"सैनिटाइज़ेशन नियम"$json$::jsonb),
  ('hi', 'site.doctor.sanitization.hint', $json$"इवेंट सहेजने से पहले हटाए जाने वाले अपने पैटर्न"$json$::jsonb),
  ('hi', 'site.doctor.sanitization.intro', $json$"अपने पैटर्न (कर्मचारी आईडी, अनुबंध संख्या) जो किसी भी चीज़ के इवेंट बनने से पहले लॉग से हटा दिए जाते हैं, प्लेटफ़ॉर्म के डिटेक्टर के अलावा।"$json$::jsonb),
  ('hi', 'site.doctor.sanitization.builtIn', $json$"प्लेटफ़ॉर्म के डिटेक्टर हमेशा चलते हैं: टोकन, कुंजियाँ, पासवर्ड, CPF, CNPJ, ईमेल, फ़ोन और कार्ड नंबर। यहाँ के नियम उनमें जुड़ते हैं और अब से आने वाले इवेंट पर लागू होते हैं।"$json$::jsonb),
  ('hi', 'site.doctor.sanitization.managersOnly', $json$"ये नियम सिर्फ़ दो-चरण सत्यापन वाला Owner या Admin बदल सकता है।"$json$::jsonb),
  ('hi', 'site.doctor.sanitization.unavailable', $json$"सैनिटाइज़ेशन नियम लोड नहीं हो सके"$json$::jsonb),
  ('hi', 'site.doctor.sanitization.ips', $json$"IP पते"$json$::jsonb),
