  ('hi', 'site.doctor.sanitization.detectIpsHint', $json$"संदेशों और फ़ील्ड में IPv4 और IPv6 [REMOVIDO:ip] बन जाते हैं।"$json$::jsonb),
  ('hi', 'site.doctor.sanitization.allowPrivate', $json$"निजी नेटवर्क के IP रखें"$json$::jsonb),
  ('hi', 'site.doctor.sanitization.allowPrivateHint', $json$"10.x, 172.16–31.x, 192.168.x जैसे IP इवेंट में रहते हैं: ये सर्वर ढूँढने में मदद करते हैं और किसी व्यक्ति की पहचान नहीं करते।"$json$::jsonb),
  ('hi', 'site.doctor.sanitization.patterns', $json$"अपने पैटर्न"$json$::jsonb),
  ('hi', 'site.doctor.sanitization.patternsHint', $json$"{max} तक। हर मेल इवेंट में [REMOVIDO:<प्रकार>] बन जाता है।"$json$::jsonb),
