  ('hi', 'site.doctor.sanitization.sampleHint', $json$"लॉग की एक लाइन चिपकाएँ और देखें कि क्या हटेगा। प्रीव्यू सिर्फ़ इसी ब्राउज़र में चलता है और कुछ भी भेजा नहीं जाता।"$json$::jsonb),
