  ('hi', 'site.doctor.sanitization.error.matchesEmpty', $json$"यह एक्सप्रेशन खाली टेक्स्ट से मेल खाता है और सब कुछ चिह्नित कर देगा। कम से कम एक अक्षर ज़रूरी करें।"$json$::jsonb),
  ('hi', 'site.doctor.sanitization.error.rejected', $json$"प्लेटफ़ॉर्म ने एक पैटर्न अस्वीकार किया: जाँचें कि एक्सप्रेशन मान्य है और उसमें नेस्टेड क्वांटिफ़ायर नहीं है।"$json$::jsonb),
