  ('ar', 'site.doctor.sanitization.intro', $json$"أنماطك الخاصة (الرقم الوظيفي، رقم العقد) التي تُزال من السجلات قبل حفظ أي شيء كحدث، إضافةً إلى كواشف المنصة."$json$::jsonb),
